// ── TEMPORAL DECLARATION (TEMPORAL v1 · Step 6.1) ────────────────────────
// CANONICAL. Snapshotted into each site by scripts/sync-cole-lib.mjs.
//
// One declaration per product, authored in the product's OWN config
// (cole/config/<id>.ts, field `temporal`). This is the ONLY hand-authored
// temporal statement in the system. lib/product-deadlines.ts — a second,
// central, hand-authored list — is retired by Step 6.2; a product that is not
// declared here is SILENT (6.3), never defaulted from anywhere else.
//
// ════════════════════════════════════════════════════════════════════════
// THE RULING THAT SHAPES THIS FILE
// ════════════════════════════════════════════════════════════════════════
// A FIXED DEADLINE IS A RECURRENCE RULE, NEVER A STORED DATE.
//
// A stored date is wrong the day after it passes. That is not a hypothetical:
// lib/product-deadlines.ts held "2026-06-30" for four AU super products and
// FRCGW held a hardcoded "2025-12-31" settlement date in its own config — both
// were silently, confidently wrong the moment they elapsed, and the FRCGW one
// drove d-30/d-7/d-1 reminders for a deadline that had already gone.
//
// So a `fixed` declaration carries { recurrence, month, day } — the RULE — and
// the resolver computes the next occurrence relative to `now`. There is no
// field in which a fixed date can be stored, so the bug cannot be re-authored.
// The only ISO dates in this system come from a CUSTOMER's answer, which is
// per-session and cannot go stale.

// ── SHARED VOCABULARY ────────────────────────────────────────────────────

/** How the date is arrived at. */
export type TemporalSource =
  | "fixed"          // a recurrence rule in law/policy (30 June, 31 January…)
  | "user_supplied"  // the customer gives the date outright (a settlement date)
  | "user_derived";  // computed from a customer answer + an offset

export type Recurrence = "annual" | "quarterly" | "monthly" | "one_off";

/** What to do when the computed date lands on a non-business day. */
export type BusinessDayShift = "none" | "next_business_day" | "prev_business_day";

/** Context every declaration carries, computable or not. */
export interface TemporalContext {
  /** ISO-3166 alpha-2, or a sub-jurisdiction like "AU-NSW". */
  jurisdiction: string;
  /** Free but conventional: "super", "property_cgt", "income_tax", "gst"… */
  domain: string;
  /** Human label used in customer-facing copy. */
  label?: string;
}

/** A fixed recurrence rule. NOTE: no date field exists here, by design. */
export interface FixedRule {
  source: "fixed";
  recurrence: Recurrence;
  /** 1-12. Required for annual; the anchor month for quarterly. */
  month?: number;
  /** 1-31. Clamped to the month's length (31 Feb → 28/29 Feb). */
  day: number;
  /** IANA zone. The date is a CALENDAR date in this zone. */
  timezone: string;
  shift: BusinessDayShift;
  /**
   * one_off only: the single calendar year the rule fires in. Present so a
   * genuine one-off (a transitional cut-over) is expressible WITHOUT
   * reintroducing a stored ISO instant — after that year the resolver returns
   * EXPIRED rather than silently rolling to next year.
   */
  year?: number;
}

/** A rule anchored to something the customer told us. */
export interface UserRule {
  source: "user_supplied" | "user_derived";
  /**
   * The answer key holding the date. Resolved against the session answers the
   * scheduler passes in; if the key is absent or unparseable the resolver
   * returns UNRESOLVABLE — it never guesses.
   */
  field: string;
  /** Applied to the customer's date. Negative days = before it. */
  offset?: { days?: number; months?: number };
  timezone: string;
  shift: BusinessDayShift;
}

export type ComputableRule = FixedRule | UserRule;

// ── THE FIVE KINDS ───────────────────────────────────────────────────────

/** Act by this date. */
export interface DeadlineDeclaration extends TemporalContext {
  kind: "deadline";
  rule: ComputableRule;
}

/** A period that opens and closes — both computable rules. */
export interface WindowDeclaration extends TemporalContext {
  kind: "window";
  opens:  ComputableRule;
  closes: ComputableRule;
}

/** The law changes at X. Not an act-by date — a state change. */
export interface EffectiveFromDeclaration extends TemporalContext {
  kind: "effective_from";
  rule: ComputableRule;
}

/**
 * There is genuinely no date. DECLARED and deliberate — the difference between
 * "we thought about it and there is none" and "nobody said". Both are silent,
 * but only one is evidence.
 */
export interface NoneDeclaration extends Partial<TemporalContext> {
  kind: "none";
  /** Why there is no date. Required: a bare "none" is not a declaration. */
  reason: string;
}

/**
 * A REAL date exists but cannot be computed from anything we hold — rolling
 * day-counts, contingent windows, a date set by a third party we never see.
 *
 * This kind exists so such a product is RECORDED rather than forced into a
 * computable kind. Manufacturing a date from a bucketed answer ("within a
 * month" → now+30d) would email a customer a deadline they never gave — the
 * same class of error as the stored date. Never do it; declare this instead.
 */
export interface UnresolvableDeclaration extends Partial<TemporalContext> {
  kind: "unresolvable";
  /** Machine-readable slug, e.g. "settlement_date_contingent_not_captured". */
  reason: string;
  /** Prose for a human reading the gate or the report. */
  detail?: string;
}

export type TemporalDeclaration =
  | DeadlineDeclaration
  | WindowDeclaration
  | EffectiveFromDeclaration
  | NoneDeclaration
  | UnresolvableDeclaration;

// ── RESOLUTION RESULT (consumed by 6.2) ──────────────────────────────────

export type TemporalStatus =
  | "UNDECLARED"    // 6.3 — no declaration at all. Silent, and NOT the same as NONE.
  | "NONE"          // declared: there is deliberately no date
  | "RESOLVED"      // a real, future (or today) calendar date
  | "UNRESOLVABLE"  // declared: a real date exists but cannot be computed
  | "EXPIRED";      // computed, but already in the past

export type TemporalResolution =
  | { status: "UNDECLARED" }
  | { status: "NONE"; reason: string }
  | { status: "UNRESOLVABLE"; reason: string; detail?: string }
  /** date is a CALENDAR date (YYYY-MM-DD) in `timezone`, never an instant. */
  | { status: "RESOLVED"; date: string; label?: string; timezone: string }
  | { status: "EXPIRED"; date: string; timezone: string };

/** A window resolves both edges; each edge is itself a resolution. */
export interface WindowResolution {
  opens:  TemporalResolution;
  closes: TemporalResolution;
}
